(()=>{
if(window.__hsjTriageIntegrated20261023)return;window.__hsjTriageIntegrated20261023=true;
const questions=[['sintomas','Nas últimas duas semanas, apresentou febre, tosse, dor de garganta, coriza ou falta de ar?'],['gi_urina','Apresentou diarreia, vômito ou infecção urinária recentemente?'],['pa_glicemia','Houve alguma alteração na pressão arterial ou glicemia nos últimos dias?'],['medicamentos','Quais medicamentos toma diariamente?'],['suspensao_meds','O médico orientou suspender algum remédio? O paciente seguiu a orientação?'],['alergias','Possui alergia conhecida a medicamentos, látex ou alimentos?'],['cirurgias_previas','Já realizou cirurgias antes?'],['jejum','Orientações de jejum de sólidos e líquidos reforçadas?'],['acompanhante','Acompanhante obrigatório confirmado?'],['documentos','Orientado a trazer exames impressos, documentos e itens pessoais?']];
const safe=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','"':'&quot;'}[c]));
const originalOpen=window.hsjAgendaSurgery;
window.hsjAgendaSurgery=async function(id){await originalOpen(id);const x=S.rows.find(x=>x.id===id);const mb=document.querySelector('#modal .mb');if(!x||!mb||!document.getElementById('ac_date'))return;
const answers=x.triage_answers||{};const html='<section style="border-top:2px solid #c4d5eb;margin-top:20px;padding-top:15px"><h3>☎ Triagem de enfermagem — pré-agendamento</h3><p class="notice">Registre as dez respostas antes de concluir o agendamento. As informações serão preservadas no cadastro.</p>'+questions.map(([k,q],i)=>'<div class="field" style="margin-bottom:12px"><label>'+(i+1)+'. '+safe(q)+' *</label>'+(['medicamentos','suspensao_meds','alergias','cirurgias_previas'].includes(k)?'<textarea rows="2" id="hsj_tri_'+k+'">'+safe(answers[k]||'')+'</textarea>':'<select id="hsj_tri_'+k+'"><option value="">Selecione</option><option value="SIM" '+(answers[k]==='SIM'?'selected':'')+'>SIM</option><option value="NÃO" '+(answers[k]==='NÃO'?'selected':'')+'>NÃO</option></select>')+'</div>').join('')+'<div class="field"><label>Observações da triagem</label><textarea id="hsj_tri_notes" rows="3">'+safe(x.triage_notes||'')+'</textarea></div></section>';
mb.insertAdjacentHTML('beforeend',html);
const footer=document.querySelector('#modal .mf');footer?.querySelectorAll('button').forEach(b=>{if(/Salvar agendamento/i.test(b.textContent))b.textContent='Salvar triagem e agendar cirurgia → Mapa Cirúrgico';});
};
window.hsjSaveSurgery=async function(id){const fields=['scheduled_date','scheduled_time','arrival_time','location','instructions','scheduled_by_name'];const val=k=>document.getElementById(({scheduled_date:'ac_date',scheduled_time:'ac_time',arrival_time:'ac_arrival',location:'ac_location',instructions:'ac_instructions',scheduled_by_name:'ac_by'})[k])?.value.trim()||'';
const answers={};for(const [k] of questions){answers[k]=document.getElementById('hsj_tri_'+k)?.value.trim()||'';}
const err=document.getElementById('ac_err');if(Object.values(answers).some(v=>!v)){if(err)err.textContent='Responda às dez perguntas da triagem antes de agendar.';return false;}
if(!val('scheduled_date')||!val('scheduled_time')||!val('scheduled_by_name')||!val('location')||!val('instructions')){if(err)err.textContent='Preencha data, hora, local, orientações e nome do responsável.';return false;}
const body={p_surgery_id:id,p_scheduled_date:val('scheduled_date'),p_scheduled_time:val('scheduled_time'),p_arrival_time:val('arrival_time')||null,p_location:val('location'),p_instructions:val('instructions'),p_scheduled_by_name:val('scheduled_by_name'),p_answers:answers,p_notes:document.getElementById('hsj_tri_notes')?.value||null};
try{await api('/rest/v1/rpc/hsj_agendar_cirurgia_com_triagem',{method:'POST',body:JSON.stringify(body)});await load();fillFilters();if(err)err.textContent='Agendamento e triagem salvos. Paciente encaminhado ao Mapa Cirúrgico.';return true;}catch(e){if(err)err.textContent='Não foi possível confirmar agendamento: '+e.message;return false;}
};
const originalSend=window.hsjSendSurgery;
window.hsjSendSurgery=async function(id,effective){if(effective){const ok=await window.hsjSaveSurgery(id);if(!ok)return;const btn=document.getElementById('ac_by');const name=btn?.value||'';const x=S.rows.find(r=>r.id===id);if(!x)return;const date=document.getElementById('ac_date').value.split('-').reverse().join('/');const digits=String(x.phone||'').replace(/\D/g,'');if(![10,11].includes(digits.length))return alert('Agendamento salvo, mas o telefone não é válido para WhatsApp.');
const msg='Olá, '+x.patient_name+'!\nAqui é do Setor de Marcação de Cirurgia do Hospital São José.\n\nProcedimento: '+(x.procedure_name||'')+'\nData: '+date+'\nHorário da cirurgia: '+document.getElementById('ac_time').value+'\nChegada: '+(document.getElementById('ac_arrival').value||'Conforme orientação')+'\nLocal: '+document.getElementById('ac_location').value+'\n\nORIENTAÇÕES:\n'+document.getElementById('ac_instructions').value+'\n\nResponsável pelo agendamento: '+name+'\nPor favor, confirme o recebimento.';window.open('https://wa.me/55'+digits+'?text='+encodeURIComponent(msg),'_blank','noopener,noreferrer');document.getElementById('modal').innerHTML='';S.view='mapa_cirurgico';renderTabs();renderCurrent();return;}
return originalSend(id,false)};
const originalSave=window.hsjSaveSurgery;
window.hsjConfirmSurgeryAndMap=async function(id){if(await originalSave(id)){document.getElementById('modal').innerHTML='';S.view='mapa_cirurgico';renderTabs();renderCurrent();}};
const show=window.hsjAgendaSurgery;
window.hsjAgendaSurgery=async function(id){await show(id);const button=[...document.querySelectorAll('#modal .mf button')].find(b=>/Salvar triagem e agendar/.test(b.textContent));if(button)button.onclick=()=>window.hsjConfirmSurgeryAndMap(id)};
const existingRenderConsult=window.renderConsult;
window.renderConsult=function(){const r=existingRenderConsult.apply(this,arguments);if(document.querySelector('#consultTableBox .notice')?.textContent.includes('Agende a cirurgia')){const box=document.getElementById('consultTableBox');const rows=box?.querySelectorAll('tbody tr');rows?.forEach(tr=>{const raw=tr.querySelector('button[onclick^="hsjAgendaSurgery"]')?.getAttribute('onclick')||'';const id=raw.match(/'([0-9a-f-]{36})'/)?.[1];const x=S.rows.find(r=>r.id===id);if(x?.stage==='mapa_cirurgico'||x?.stage==='concluida')tr.remove()})}return r;};
const oldTabs=window.renderTabs;
window.renderTabs=function(){const index=views.indexOf('entrevista_tecnico');if(index>=0)views.splice(index,1);const r=oldTabs.apply(this,arguments);document.querySelectorAll('#tabs .tab').forEach(b=>{if(/triagem de enfermagem/i.test(b.textContent))b.remove()});return r;};
window.renderTabs();
})();